import React, { useState, useEffect, useRef } from 'react';
import './AlbumDetail.css';

function AlbumDetail({ allerVers, utilisateur, albumId }) {
  const [album, setAlbum] = useState(null);
  const [pistes, setPistes] = useState([]);
  const [chargement, setChargement] = useState(true);
  const [lecteurActif, setLecteurActif] = useState(null);
  const audioRef = useRef(null);

  useEffect(() => {
    fetch(`/api/musiques/${albumId}/pistes`)
      .then(res => res.json())
      .then(data => {
        setAlbum(data.album);
        setPistes(data.pistes);
        setChargement(false);
      })
      .catch(() => setChargement(false));
  }, [albumId]);

  const jouerExtrait = (piste) => {
    if (lecteurActif === piste.id) {
      audioRef.current.pause();
      setLecteurActif(null);
    } else {
      if (audioRef.current) audioRef.current.pause();
      audioRef.current = new Audio(piste.fichier_url);
      audioRef.current.play();
      setLecteurActif(piste.id);
      setTimeout(() => {
        if (audioRef.current) audioRef.current.pause();
        setLecteurActif(null);
      }, 20000);
    }
  };

  if (chargement) return (
    <div className="album-detail-page">
      <div className="chargement">Chargement de l'album...</div>
    </div>
  );

  if (!album) return (
    <div className="album-detail-page">
      <div className="chargement">Album introuvable.</div>
    </div>
  );

  return (
    <div className="album-detail-page">
      <header className="header">
        <div className="logo" onClick={() => allerVers('accueil')}>🎵 Varim Music</div>
        <nav className="nav">
          <a href="#" onClick={() => allerVers('accueil')}>Accueil</a>
          <a href="#" onClick={() => allerVers('catalogue')}>Catalogue</a>
        </nav>
        <div className="auth-buttons">
          {utilisateur ? (
            <>
              <span className="user-prenom">👋 {utilisateur.prenom}</span>
              <button className="btn-login" onClick={() => {
                localStorage.removeItem('token');
                localStorage.removeItem('utilisateur');
                allerVers('accueil');
              }}>Déconnexion</button>
            </>
          ) : (
            <>
              <button className="btn-login" onClick={() => allerVers('login')}>Connexion</button>
              <button className="btn-register" onClick={() => allerVers('register')}>S'inscrire</button>
            </>
          )}
        </div>
      </header>

      <div className="album-contenu">
        <button className="btn-retour" onClick={() => allerVers('catalogue')}>
          ← Retour au catalogue
        </button>

        <div className="album-header">
          <div className="album-pochette">
            {album.pochette_url ? (
              <img src={album.pochette_url} alt={album.titre} />
            ) : (
              <div className="pochette-defaut">💿</div>
            )}
          </div>
          <div className="album-meta">
            <span className="album-badge">💿 Album</span>
            <h1 className="album-titre">{album.titre}</h1>
            <p className="album-artiste" style={{cursor:'pointer'}} onClick={() => allerVers('profil_' + album.artiste_id)}>
  🎤 {album.nom_artiste}
</p>
            <p className="album-genre">🎸 {album.genre}</p>
            <p className="album-nb-pistes">{pistes.length} piste{pistes.length > 1 ? 's' : ''}</p>
            <p className="album-prix">{album.prix} FCFA</p>
            <button
              className="btn-acheter-album"
              onClick={() => allerVers('achat_' + album.id)}
            >
              🛒 Acheter l'album
            </button>
          </div>
        </div>

        <div className="pistes-liste">
          <h2>🎵 Pistes de l'album</h2>
          {pistes.map((piste) => (
            <div key={piste.id} className="piste-ligne">
              <span className="piste-num">#{piste.numero_ordre}</span>
              <span className="piste-titre">{piste.titre}</span>
              <button
                className={`btn-extrait-piste ${lecteurActif === piste.id ? 'en-lecture' : ''}`}
                onClick={() => jouerExtrait(piste)}
              >
                {lecteurActif === piste.id ? '⏸ Stop' : '▶ Extrait 20s'}
              </button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default AlbumDetail;
